INSERT INTO `soal` VALUES ('2425','14','32','<p>Apa yang dimaksud dengan \"influencer\" dalam dunia konten kreator?</p>','1','<p>Orang yang hanya menonton konten online.</p>','<p>Orang yang membuat konten hanya untuk diri mereka sendiri.</p>','<p>Orang yang memiliki pengaruh besar di media sosial dan sering digandeng oleh merek untuk mempromosikan produk atau layanan.</p>','<p>Orang yang hanya mengikuti tren terbaru.</p>','<p>Orang yang tidak terlibat dalam media sosial.</p>','C','','','','','','','');
