INSERT INTO `soal` VALUES ('2516','30','3','Cara mengubah musik dimana satu  suara menjadi suara utama (lead) akan diikuti oleh suara-suara lain yang disusun, dikoordinasikan, ditata, dan dirangkai mengikuti suara utama disebut dengan istilah....','1','Komposisi musik','Komponen musik','Musik campuran','Kolega musik','Koreografi musik','A',NULL,'','','','','','');
