INSERT INTO `soal` VALUES ('2518','30','5','<p>Dalam musik klasik biasanya komposer menulis dengan lengkap bagian per bagian yang dituangkan dalam lembaran musik atau music sheet. Apa saja yang biasanya ditulis dalam music sheet ?</p>','1','<p>Irama, tempo dan hitungan</p>','<p>Birama, tempo dan ketukan</p>','<p>Ketukan, tempo dan ritme</p>','<p>Tempo, hitungan birama dan notasi lengkap</p>','<p>Judul, lirik dan intro</p>','D','','','','','','','');
