INSERT INTO `soal` VALUES ('2520','30','7','Apa yang dimaksud dengan aransemen ?','1','Intrumen musik yang didasarkan atas sebuah komposisi yang telah ada sehingga esensi musiknya berubah','Intrumen musik yang didasarkan atas sebuah komposisi yang telah ada sehingga esensi musiknya tidak berubah','Intrumen musik yang tidak didasarkan atas sebuah komposisi yang telah ada sehingga esensi musiknya tidak berubah','Intrumen musik yang didasarkan atas sebuah komposisi baru yang esensi musiknya tidak berubah','Penggabungan dari beberapa aliran musik','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2521','30','8','<p>Bagian-bagian aransemen musik dikenal dengan beberapa istilah. Dari istilah dibawah ini manakah istilah yang berasal dari daerah belanda, italia, inggris &amp; perancis berdasarkan urutan negaranya ?</p>','1','<p>Part, partituur, partitura dan parte</p>','<p>Parte, partitura, partituur dan part</p>','<p>Partitura,parte, part dan partituur</p>','<p>Parte, part, partitura dan partituur</p>','<p>Partituur, partitura, part dan parte</p>','E','','','','','','','');
