INSERT INTO `soal` VALUES ('2548','30','35','Talempong unggan merupakan kesenian tradisional dari daerah sumpur kudus sijunjung, salah satu judul lagu dari permainan talempong unggan adalah?','1','Sikudidi','Sialang','Kajabakaja','Tupai bagaluik','Siamang tagagau','B',NULL,'','','','','','');
