INSERT INTO `soal` VALUES ('3103','13','30','Di bawah ini yang termasuk faktor penting dalam mendesain kemasan adalah ....','1','Biaya tenaga kerja','Fungsi, bahan, dan tampilan visual.','Kesulitan dalam pembukaan','Berat produk sebelum dikemas','Kesamaan bentuk dengan produk pesaing','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('3104','13','31','Label pada kemasan produk berfungsi sebagai &hellip;.','1','Alat komunikasi antara produsen dengan konsumen.','Alat promosi penjualan langsung','Alat transportasi produk','Pengganti garansi                   ','Penentu harga akhir                                                      ','A',NULL,'','','','','','');
