INSERT INTO `soal` VALUES ('3107','13','34','Jika terjadi ketidak sesuaian antara barang yang diterima dan dokumen pesanan, langkah yang tepat adalah...','1','Melanjutkan proses penyimpanan barang','Menghubungi pemasok untuk klarifikasi','Mengirimkan barang kembali ke pengirim','Menyimpan barang tanpa pengecekan lebih lanjut','Mencatat barang yang diterima tanpa tindakan lebih lanjut','B',NULL,'','','','','','');
